const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const sistanBaluchestan = ee.Geometry.Rectangle([58.0, 25.0, 63.5, 31.5]); // Approximate bounds
  const startDate = '2020-01-08';
  const endDate = '2020-01-16'; // Exclusive end date

  // 2. Data Acquisition - GPM daily precipitation
  let precipCol = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .filterBounds(sistanBaluchestan)
    .select('precipitationCal'); // Calibrated precipitation in mm/hr

  const colSize = precipCol.size().getInfo();
  console.log(`GPM Images found: ${colSize}`);

  if (colSize === 0) {
    console.log("No GPM data available for the period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum precipitation over the period
  // GPM provides mm/hr in 30-minute intervals, so we need to multiply by 0.5 hours
  const totalPrecip = precipCol.map(function(img) {
    return img.multiply(0.5); // Convert mm/hr to mm per 30-min interval
  }).sum();

  // 4. Calculate mean precipitation over the region
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: sistanBaluchestan,
    scale: 11000,
    maxPixels: 1e9
  });

  const precipMean = stats.get('precipitationCal_mean').getInfo();
  const pixelCount = stats.get('precipitationCal_count').getInfo();

  console.log(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid pixels after processing.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (precipMean === null || precipMean === undefined || isNaN(precipMean)) {
    console.log("Calculation returned invalid result.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Check for unrealistic values
  if (precipMean < 0 || precipMean > 1000) {
    console.log(`Invalid precipitation value: ${precipMean} mm`);
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Convert mm to inches and compare
  const precipInches = precipMean / 25.4;
  const threshold = 3.0;

  console.log(`Total precipitation: ${precipMean.toFixed(2)} mm (${precipInches.toFixed(2)} inches)`);
  console.log(`Threshold: ${threshold} inches (${(threshold * 25.4).toFixed(2)} mm)`);

  if (precipInches > threshold) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
